package com.acme.order.order;
import com.acme.order.api.inventory.InventoryDtos.*;import com.acme.order.api.payment.PaymentDtos;import com.acme.order.api.product.ProductDtos.SkuView;import com.acme.order.common.core.ApiResponse;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.core.ParameterizedTypeReference;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.util.List;
@Component public class RemoteClients {private final RestClient product,inventory,payment;public RemoteClients(@Qualifier("productClient")RestClient p,@Qualifier("inventoryClient")RestClient i,@Qualifier("paymentClient")RestClient pay){product=p;inventory=i;payment=pay;}public SkuView sku(long id){return product.get().uri("/internal/skus/{id}",id).retrieve().body(new ParameterizedTypeReference<ApiResponse<SkuView>>(){}).data();}public void reserve(String no,long user,List<Line> lines){inventory.post().uri("/internal/inventory/reserve").body(new ReserveRequest(no,user,lines)).retrieve().toBodilessEntity();}public void release(String no){inventory.post().uri("/internal/inventory/release").body(new ChangeRequest(no)).retrieve().toBodilessEntity();}public PaymentDtos.PayView createPayment(String no,long user,long amount){return payment.post().uri("/internal/payments").body(new PaymentDtos.CreateRequest(no,user,amount)).retrieve().body(new ParameterizedTypeReference<ApiResponse<PaymentDtos.PayView>>(){}).data();}}
